/* Schwung v2 adapter: maps the plugin ABI onto the TinySID engine.
 *
 * Besides the engine's parameters the host reads a few documents through get_param():
 * ui_hierarchy and chain_params (generated from module.json), preset_count, name and
 * state. Without ui_hierarchy the host falls back to an empty preset browser. */
#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "schwung_api.h"
#include "tinysid.h"

#include "default_sid.h"          /* default_sid_data / default_sid_len, generated by scripts/build.sh */
#include "ui_json.h"              /* ui_hierarchy_json / chain_params_json, generated from module.json */

#define SAMPLE_RATE 44100.0
#define SCRATCH_FRAMES 512
#define PATH_MAX_LEN 240

static const host_api_v1_t *g_host;

typedef struct {
    tinysid_t *engine;
    char error[160];
    char module_dir[PATH_MAX_LEN];
    char load_path[PATH_MAX_LEN];     /* last file picked with sid_file, kept for the saved state */
    float left[SCRATCH_FRAMES], right[SCRATCH_FRAMES];
} instance_t;

/* Parameters saved with a set, in restore order: the subtune re-inits the tune, so it goes first. */
static const struct { const char *key; int quoted; const char *read_key; } k_state[] = {
    { "subtune", 0, NULL }, { "v1_vol", 0, NULL }, { "v2_vol", 0, NULL }, { "v3_vol", 0, NULL }, { "out_trim", 0, NULL },
    { "sync_mode", 1, NULL }, { "tempo_trim", 0, NULL }, { "chip_model", 1, NULL }, { "filter_mode", 1, NULL },
    { "cutoff_bias", 0, NULL }, { "res_bias", 0, NULL },
    /* the pad sound is saved as its list position: instrument names only exist once the tune has been scanned */
    { "pad_sound", 0, "pad_sound_index" }, { "pad_target", 1, NULL }, { "snoop_voice", 1, NULL }
};
#define STATE_KEYS ((int)(sizeof(k_state) / sizeof(k_state[0])))

static void *create_instance(const char *module_dir, const char *json_defaults)
{
    (void)json_defaults;
    instance_t *inst = calloc(1, sizeof(*inst));
    if (!inst) return NULL;

    inst->engine = tinysid_create(SAMPLE_RATE);
    if (!inst->engine) {
        free(inst);
        return NULL;
    }
    snprintf(inst->module_dir, sizeof(inst->module_dir), "%s", module_dir ? module_dir : "");
    if (g_host && g_host->get_clock_status) tinysid_set_clock_status_fn(inst->engine, g_host->get_clock_status);
    int err = tinysid_load(inst->engine, default_sid_data, default_sid_len);
    if (err != PSID_OK) snprintf(inst->error, sizeof(inst->error), "default tune: %s", psid_strerror(err));
    return inst;
}

static void destroy_instance(void *p)
{
    instance_t *inst = p;
    if (!inst) return;
    tinysid_destroy(inst->engine);
    free(inst);
}

static void on_midi(void *p, const uint8_t *msg, int len, int source)
{
    (void)source;
    instance_t *inst = p;
    if (inst) tinysid_midi(inst->engine, msg, len);
}

/* ---- saved state: a flat JSON object of parameter values ------------------- */

static int build_state(instance_t *inst, char *buf, int buf_len)
{
    int n = 0;
    n += snprintf(buf + n, (size_t)(buf_len - n), "{");
    if (inst->load_path[0]) n += snprintf(buf + n, (size_t)(buf_len - n), "\"sid_file\":\"%s\",", inst->load_path);
    for (int i = 0; i < STATE_KEYS && n < buf_len; i++) {
        char v[64];
        if (tinysid_get_param(inst->engine, k_state[i].read_key ? k_state[i].read_key : k_state[i].key, v, sizeof(v)) < 0) continue;
        n += snprintf(buf + n, (size_t)(buf_len - n), k_state[i].quoted ? "\"%s\":\"%s\"," : "\"%s\":%s,", k_state[i].key, v);
    }
    if (n >= buf_len - 1) return -1;
    if (buf[n - 1] == ',') n--;
    buf[n++] = '}';
    buf[n] = '\0';
    return n;
}

/* Reads one "key": value pair; value text is copied without quotes. Returns the position after it or NULL. */
static const char *next_pair(const char *p, char *key, size_t key_size, char *val, size_t val_size)
{
    while (*p && *p != '"') p++;
    if (!*p) return NULL;
    size_t n = 0;
    for (p++; *p && *p != '"'; p++) if (n + 1 < key_size) key[n++] = *p;
    key[n] = '\0';
    if (*p) p++;
    while (*p && (*p == ':' || isspace((unsigned char)*p))) p++;
    n = 0;
    if (*p == '"') {
        for (p++; *p && *p != '"'; p++) if (n + 1 < val_size) val[n++] = *p;
        if (*p) p++;
    } else {
        for (; *p && *p != ',' && *p != '}'; p++) if (n + 1 < val_size && !isspace((unsigned char)*p)) val[n++] = *p;
    }
    val[n] = '\0';
    return p;
}

static void set_param(void *p, const char *key, const char *val);

/* The host writes keys this module has never heard of (preset, ...). Those are ignored quietly: the host shows
 * every reported error as a warning. Only a bad value for one of our own parameters is worth reporting. */
static int is_own_param(instance_t *inst, const char *key)
{
    char scratch[8];
    return tinysid_get_param(inst->engine, key, scratch, sizeof(scratch)) >= 0 || !strcmp(key, "song_bpm_override");
}

static void apply_state(instance_t *inst, const char *json)
{
    char key[48], val[PATH_MAX_LEN];
    const char *p = json;

    /* the file first (it may change the subtune count), then the keys in k_state order */
    while ((p = next_pair(p, key, sizeof(key), val, sizeof(val))) != NULL)
        if ((!strcmp(key, "sid_file") || !strcmp(key, "load_path")) && val[0]) set_param(inst, "sid_file", val);
    for (int i = 0; i < STATE_KEYS; i++) {
        p = json;
        while ((p = next_pair(p, key, sizeof(key), val, sizeof(val))) != NULL)
            if (!strcmp(key, k_state[i].key)) set_param(inst, key, val);
    }
}

/* ---- host entry points --------------------------------------------------------- */

static void set_param(void *p, const char *key, const char *val)
{
    instance_t *inst = p;
    if (!inst || !key || !val) return;

    if (!strcmp(key, "state")) {
        apply_state(inst, val);
        return;
    }
    if (!strcmp(key, "sid_file") || !strcmp(key, "load_path")) {
        if (!val[0]) return;                           /* the picker's default is empty: nothing chosen */
        key = "load_path";
        if (tinysid_set_param(inst->engine, key, val) != 0) {
            snprintf(inst->error, sizeof(inst->error), "cannot load %s", val);
            return;
        }
        int storable = strlen(val) < PATH_MAX_LEN && !strpbrk(val, "\"\\");
        snprintf(inst->load_path, sizeof(inst->load_path), "%s", storable ? val : "");
        return;
    }
    if (tinysid_set_param(inst->engine, key, val) != 0 && is_own_param(inst, key))
        snprintf(inst->error, sizeof(inst->error), "bad param %s=%s", key, val);
}

static int copy_out(const char *s, char *buf, int buf_len)
{
    int len = (int)strlen(s);
    if (len >= buf_len) return -1;                 /* never hand the host a truncated JSON document */
    memcpy(buf, s, (size_t)len + 1);
    return len;
}

/* chain_params with the subtune range set to the loaded file's real subtune count, the file picker
 * starting in the module's own sids/ folder, and the Pad Sound list naming this tune's instruments. */
static int chain_params(instance_t *inst, char *buf, int buf_len)
{
    char count[16], sids[PATH_MAX_LEN + 8];
    if (tinysid_get_param(inst->engine, "subtune_count", count, sizeof(count)) <= 0 || atoi(count) < 1)
        snprintf(count, sizeof(count), "256");
    if (inst->module_dir[0] && !strpbrk(inst->module_dir, "\"\\"))
        snprintf(sids, sizeof(sids), "%s/sids", inst->module_dir);
    else
        snprintf(sids, sizeof(sids), "/data/UserData");

    char pad_options[700];
    if (tinysid_pad_options(inst->engine, pad_options, sizeof(pad_options)) < 0) snprintf(pad_options, sizeof(pad_options), "[\"Lead\"]");
    static const char t_max[] = "@SUBTUNE_MAX@", t_dir[] = "@SIDS_DIR@", t_pad[] = "@PAD_OPTIONS@";
    const char *src = chain_params_json;
    int n = 0;
    while (*src) {
        const char *with = NULL;
        size_t skip = 0;
        if (!strncmp(src, t_max, sizeof(t_max) - 1)) { with = count; skip = sizeof(t_max) - 1; }
        else if (!strncmp(src, t_dir, sizeof(t_dir) - 1)) { with = sids; skip = sizeof(t_dir) - 1; }
        else if (!strncmp(src, t_pad, sizeof(t_pad) - 1)) { with = pad_options; skip = sizeof(t_pad) - 1; }
        size_t len = with ? strlen(with) : 1;
        if (n + (int)len >= buf_len) return -1;          /* never hand the host a truncated document */
        if (with) { memcpy(buf + n, with, len); src += skip; }
        else buf[n] = *src++;
        n += (int)len;
    }
    buf[n] = '\0';
    return n;
}

static int get_param(void *p, const char *key, char *buf, int buf_len)
{
    instance_t *inst = p;
    if (!inst || !key || !buf || buf_len <= 0) return -1;

    if (!strcmp(key, "ui_hierarchy")) return copy_out(ui_hierarchy_json, buf, buf_len);
    if (!strcmp(key, "chain_params")) return chain_params(inst, buf, buf_len);
    if (!strcmp(key, "name")) return copy_out("TinySID", buf, buf_len);
    if (!strcmp(key, "preset_count")) return copy_out("0", buf, buf_len);
    if (!strcmp(key, "state")) return build_state(inst, buf, buf_len);
    if (!strcmp(key, "sid_file")) return copy_out(inst->load_path, buf, buf_len);
    return tinysid_get_param(inst->engine, key, buf, buf_len);
}

static int get_error(void *p, char *buf, int buf_len)
{
    instance_t *inst = p;
    if (!inst || !buf || buf_len <= 0) return 0;
    int n = snprintf(buf, (size_t)buf_len, "%s", inst->error);
    inst->error[0] = '\0';
    return n >= buf_len ? buf_len - 1 : n;
}

static void render_block(void *p, int16_t *out, int frames)
{
    instance_t *inst = p;
    if (!inst) {
        memset(out, 0, (size_t)frames * 2 * sizeof(int16_t));
        return;
    }
    int done = 0;
    while (done < frames) {
        int n = frames - done;
        if (n > SCRATCH_FRAMES) n = SCRATCH_FRAMES;
        tinysid_render(inst->engine, inst->left, inst->right, n);
        for (int i = 0; i < n; i++) {
            out[(done + i) * 2] = (int16_t)(inst->left[i] * 32767.0f);
            out[(done + i) * 2 + 1] = (int16_t)(inst->right[i] * 32767.0f);
        }
        done += n;
    }
}

static plugin_api_v2_t g_api = {
    SCHWUNG_PLUGIN_API_VERSION,
    create_instance, destroy_instance, on_midi, set_param, get_param, get_error, render_block
};

__attribute__((visibility("default")))
plugin_api_v2_t *SCHWUNG_INIT_SYMBOL(const host_api_v1_t *host)
{
    g_host = host;
    return &g_api;
}
